import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ChevronRight, Users, TrendingUp, Award } from 'lucide-react';

function Onboarding() {
  const [currentSlide, setCurrentSlide] = useState(0);
  const navigate = useNavigate();

  const slides = [
    {
      icon: <Users size={80} color="#FF9933" />,
      title: 'Welcome to Kartavya',
      description: 'Your civic duty, your voice. Report issues and make your community better.',
      color: '#FF9933'
    },
    {
      icon: <TrendingUp size={80} color="#138808" />,
      title: 'Track Progress',
      description: 'See real-time updates on reported issues and their resolution status.',
      color: '#138808'
    },
    {
      icon: <Award size={80} color="#000080" />,
      title: 'Earn Rewards',
      description: 'Get points for reporting issues and climb the community leaderboard.',
      color: '#000080'
    }
  ];

  const handleNext = () => {
    if (currentSlide < slides.length - 1) {
      setCurrentSlide(currentSlide + 1);
    } else {
      navigate('/login');
    }
  };

  const handleSkip = () => {
    navigate('/login');
  };

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      background: 'linear-gradient(135deg, #FF9933 0%, #138808 100%)',
      padding: '20px'
    }}>
      <div style={{
        maxWidth: '500px',
        width: '100%',
        backgroundColor: 'white',
        borderRadius: '24px',
        padding: '40px',
        boxShadow: '0 10px 40px rgba(0,0,0,0.2)',
        textAlign: 'center'
      }}>
        {/* Icon */}
        <div style={{ marginBottom: '30px' }}>
          {slides[currentSlide].icon}
        </div>

        {/* Title */}
        <h1 style={{
          fontSize: '28px',
          fontWeight: '700',
          color: slides[currentSlide].color,
          marginBottom: '15px'
        }}>
          {slides[currentSlide].title}
        </h1>

        {/* Description */}
        <p style={{
          fontSize: '16px',
          color: '#666',
          lineHeight: '1.6',
          marginBottom: '40px'
        }}>
          {slides[currentSlide].description}
        </p>

        {/* Dots Indicator */}
        <div style={{
          display: 'flex',
          justifyContent: 'center',
          gap: '10px',
          marginBottom: '30px'
        }}>
          {slides.map((_, index) => (
            <div
              key={index}
              style={{
                width: currentSlide === index ? '30px' : '10px',
                height: '10px',
                borderRadius: '5px',
                backgroundColor: currentSlide === index ? '#FF9933' : '#E0E0E0',
                transition: 'all 0.3s ease'
              }}
            />
          ))}
        </div>

        {/* Buttons */}
        <div style={{
          display: 'flex',
          gap: '15px'
        }}>
          <button
            onClick={handleSkip}
            style={{
              flex: 1,
              padding: '14px',
              backgroundColor: 'transparent',
              color: '#666',
              border: '2px solid #E0E0E0',
              borderRadius: '12px',
              fontSize: '16px',
              fontWeight: '600',
              cursor: 'pointer',
              fontFamily: 'Poppins, sans-serif'
            }}
          >
            Skip
          </button>
          <button
            onClick={handleNext}
            style={{
              flex: 1,
              padding: '14px',
              backgroundColor: '#FF9933',
              color: 'white',
              border: 'none',
              borderRadius: '12px',
              fontSize: '16px',
              fontWeight: '600',
              cursor: 'pointer',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              gap: '8px',
              fontFamily: 'Poppins, sans-serif'
            }}
          >
            {currentSlide === slides.length - 1 ? 'Get Started' : 'Next'}
            <ChevronRight size={20} />
          </button>
        </div>
      </div>
    </div>
  );
}

export default Onboarding;
